        , cast(null as varchar) as SUB_LIMIT_AMOUNT
        , cast(null as varchar) as WAITING_PERIOD
        , cast(null as varchar) as CO_PAYMENT_AMOUNT
        , cast(null as varchar) as CO_PAYMENT_PERCENTAGE
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(COVER_CODE), ''), '') as COVERAGE_REFERENCE
        , coalesce(nullif(trim(COVER_NO), ''), '') as COVERAGE_SEQUENCE
        , COVER_PREM as PREMIUM_FOR_COVERAGE
        , cast(null as varchar) as SUM_INSURED
        , cast(null as varchar) as COVERAGE_OPTED_INDICATOR
        , cast(null as varchar) as DEDUCTIBLE_AMOUNT
        , cast(null as varchar) as SUB_LIMIT_AMOUNT
        , cast(null as varchar) as WAITING_PERIOD
        , cast(null as varchar) as CO_PAYMENT_AMOUNT
        , cast(null as varchar) as CO_PAYMENT_PERCENTAGE
        , 'BJAZ_CTNGY_COVERS_EXT' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_covers_ext') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(COVER_CODE), ''), '') as COVERAGE_REFERENCE
        , coalesce(nullif(trim(COVER_NO), ''), '') as COVERAGE_SEQUENCE
        , COVER_PREM as PREMIUM_FOR_COVERAGE
        , cast(null as varchar) as SUM_INSURED
        , cast(null as varchar) as COVERAGE_OPTED_INDICATOR
        , cast(null as varchar) as DEDUCTIBLE_AMOUNT
        , cast(null as varchar) as SUB_LIMIT_AMOUNT
        , cast(null as varchar) as WAITING_PERIOD
        , cast(null as varchar) as CO_PAYMENT_AMOUNT
        , cast(null as varchar) as CO_PAYMENT_PERCENTAGE
        , 'BJAZ_STARPKG_COVER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_cover_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__reg_no))) as HUB_POLICY_HK
        , 'MATERNITY' as COVERAGE_REFERENCE
        , cast(null as varchar) as COVERAGE_SEQUENCE
        , cast(null as varchar) as PREMIUM_FOR_COVERAGE
        , cast(null as varchar) as SUM_INSURED
        , cast(null as varchar) as COVERAGE_OPTED_INDICATOR
        , cast(null as varchar) as DEDUCTIBLE_AMOUNT
        , maternity_benefit as SUB_LIMIT_AMOUNT
        , cast(null as varchar) as WAITING_PERIOD
        , cast(null as varchar) as CO_PAYMENT_AMOUNT
        , cast(null as varchar) as CO_PAYMENT_PERCENTAGE
        , 'BJAZ_GRP_HLT_COVERAGE_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_coverage_dtls') }}
    where (nullif(trim(reg_no),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(COVER_CODE), ''), '') as COVERAGE_REFERENCE
        , coalesce(nullif(trim(COVER_NO), ''), '') as COVERAGE_SEQUENCE
        , FTPREMIUM_SYS_WHOLE_COVER as PREMIUM_FOR_COVERAGE
        , SUM_INSURED_WHOLE_COVER as SUM_INSURED
        , cast(null as varchar) as COVERAGE_OPTED_INDICATOR
        , cast(null as varchar) as DEDUCTIBLE_AMOUNT
        , cast(null as varchar) as SUB_LIMIT_AMOUNT
        , cast(null as varchar) as WAITING_PERIOD
        , cast(null as varchar) as CO_PAYMENT_AMOUNT
        , cast(null as varchar) as CO_PAYMENT_PERCENTAGE
        , 'OCP_POLICY_COVERS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ocp_policy_covers') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        COVERAGE_REFERENCE,
        COVERAGE_SEQUENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PREMIUM_FOR_COVERAGE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREMIUM_FOR_COVERAGE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then PREMIUM_FOR_COVERAGE end)) as PREMIUM_FOR_COVERAGE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SUM_INSURED end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then SUM_INSURED end)) as SUM_INSURED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then COVERAGE_OPTED_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVERAGE_OPTED_INDICATOR end)) as COVERAGE_OPTED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DEDUCTIBLE_AMOUNT end) as DEDUCTIBLE_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SUB_LIMIT_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then SUB_LIMIT_AMOUNT end)) as SUB_LIMIT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then WAITING_PERIOD end) as WAITING_PERIOD,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CO_PAYMENT_AMOUNT end) as CO_PAYMENT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CO_PAYMENT_PERCENTAGE end) as CO_PAYMENT_PERCENTAGE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, COVERAGE_REFERENCE, COVERAGE_SEQUENCE
),

hashed as (
    select
        *,
        case when COVERAGE_REFERENCE is not null or COVERAGE_SEQUENCE is not null or PREMIUM_FOR_COVERAGE is not null or SUM_INSURED is not null or COVERAGE_OPTED_INDICATOR is not null or DEDUCTIBLE_AMOUNT is not null or SUB_LIMIT_AMOUNT is not null or WAITING_PERIOD is not null or CO_PAYMENT_AMOUNT is not null or CO_PAYMENT_PERCENTAGE is not null
                     then md5(upper(coalesce(cast(COVERAGE_REFERENCE as varchar), '') || '|' || coalesce(cast(COVERAGE_SEQUENCE as varchar), '') || '|' || coalesce(cast(PREMIUM_FOR_COVERAGE as varchar), '') || '|' || coalesce(cast(SUM_INSURED as varchar), '') || '|' || coalesce(cast(COVERAGE_OPTED_INDICATOR as varchar), '') || '|' || coalesce(cast(DEDUCTIBLE_AMOUNT as varchar), '') || '|' || coalesce(cast(SUB_LIMIT_AMOUNT as varchar), '') || '|' || coalesce(cast(WAITING_PERIOD as varchar), '') || '|' || coalesce(cast(CO_PAYMENT_AMOUNT as varchar), '') || '|' || coalesce(cast(CO_PAYMENT_PERCENTAGE as varchar), '')))
                end as SAT_POLICY_COVERAGE_SCHEDULE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_COVERAGE_SCHEDULE_HASHDIFF is not null
